body.script:
function colorOf(id) {
  return getComputedStyle(document.getElementById(id)).color;
}

test(() => {
  assert_equals(colorOf("descendant"), "rgb(0, 128, 0)");
}, "Class selector matches an ancestor in an XML namespace");

test(() => {
  assert_equals(colorOf("child"), "rgb(0, 128, 0)");
}, "Class selector matches a parent in an XML namespace");

test(() => {
  assert_equals(colorOf("next-sibling"), "rgb(0, 128, 0)");
}, "Class selector matches a previous sibling in an XML namespace");

test(() => {
  assert_equals(colorOf("dynamic"), "rgb(255, 0, 0)");
  document.getElementById("wrap").setAttribute("class", "dynamic");
  assert_equals(colorOf("dynamic"), "rgb(0, 128, 0)");
  document.getElementById("wrap").removeAttribute("class");
  assert_equals(colorOf("dynamic"), "rgb(255, 0, 0)");
}, "Changing class on an ancestor in an XML namespace updates style");
